<script>
import VueQr from 'vue-qr'
import { Init } from '@/api/common'
export default {
  name: 'ShareOnes',
  // eslint-disable-next-line vue/no-unused-components
  components: { VueQr },
  data() {
    return {
      inviteCode: '',
      shareList: [
        {
          img: require('@/assets/img/common/fenxiang.png'),
          name: 'Share'
        },
        {
          img: require('@/assets/img/common/img_wa.png'),
          name: 'WhatsApp'
        },
        {
          img: require('@/assets/img/common/img_tg.png'),
          name: 'Telegram'
        },
        {
          img: require('@/assets/img/common/huohua.png'),
          name: 'Instagram'
        },
        {
          img: require('@/assets/img/common/youtub.png'),
          name: 'Youtobe'
        },
        {
          img: require('@/assets/img/common/img_facebook.png'),
          name: 'Facebook'
        },
        {
          img: require('@/assets/img/common/douyin.png'),
          name: 'Tiktok'
        },
        {
          img: require('@/assets/img/common/img_x.png'),
          name: 'X'
        }
      ],
      InitDate: [
        { vipLevel: '1', reward: '1', ratino: '0.50%' },
        { vipLevel: '2', reward: '300.000', ratino: '1.50%' },
        { vipLevel: '3', reward: '900.000', ratino: '2.00%' },
        { vipLevel: '4', reward: '1.500.000', ratino: '4.00%' },
        { vipLevel: '5', reward: '3.000.000', ratino: '5.00%' }
      ]
    }
  },
  mounted() {
    this.Init()
  },
  methods: {
    shareContent(i) {
      if (i === 0) {
        if (navigator.share) {
          navigator
            .share({
              title: 'OT.GAME',
              text: 'OT.GAME',
              url: this.inviteCode
            })
            .catch((err) => {
              console.error(err)
            })
        } else {
          alert('Your browser does not support the Web Share API.')
        }
      } else if (i === 1) {
        window.open(`https://api.whatsapp.com/`, '_blank')
      } else if (i === 2) {
        window.open(`https://t.me/`, '_blank')
      } else if (i === 3) {
        window.open(`https://www.instagram.com/`, '_blank')
      } else if (i === 4) {
        window.open(`https://www.youtube.com/`, '_blank')
      } else if (i === 5) {
        window.open(`https://www.facebook.com/`, '_blank')
      } else if (i === 6) {
        window.open(`https://www.tiktok.com/`, '_blank')
      } else if (i === 7) {
        window.open(`https://x.com/`, '_blank')
      }
    },
    async Init() {
      const data = await Init()
      if (data.status === 'ok') {
        this.inviteCode =
          window.location.origin +
          '/' +
          localStorage.getItem('country') +
          '/home?id=' +
          data.content.inviteCode
      }
    },
    copyText() {
      const textarea = document.createElement('textarea')
      textarea.value = this.inviteCode
      document.body.appendChild(textarea)
      textarea.select()
      document.execCommand('copy')
      document.body.removeChild(textarea)
      this.$toast({
        message: this.$lang.Sucesso,
        icon: 'success'
      })
    }
  }
}
</script>
